    .reg .u32 %tid_x, %block_dim_x, %block_idx_x, %idx;
    .reg .u64 %in_ptr, %out_ptr, %offset, %in_addr, %out_addr;
    .reg .f16 %f_in, %f_out;
    .reg .f32 %f32_tmp;
