    // load kernel arguments
    ld.param.u64 %in_ptr, [input_ptr];
    ld.param.u64 %out_ptr, [output_ptr];
    ld.param.u32 %N, [N];

    // thread identifiers
    mov.u32 %tid_x, %tid.x;
    mov.u32 %block_dim_x, %ntid.x;
    mov.u32 %block_idx_x, %ctaid.x;

    // linear global index = blockIdx.x * blockDim.x + threadIdx.x
    mul.lo.u32 %idx, %block_idx_x, %block_dim_x;
    add.u32 %idx, %idx, %tid_x;

    // bounds check: if idx >= N return
    setp.ge.u32 %p, %idx, %N;
    @%p ret;

    // byte offset for half (2 bytes per element)
    cvt.u64.u32 %offset, %idx;
    mul.lo.u64 %offset, %offset, 2;

    // compute absolute addresses
    add.u64 %in_addr, %in_ptr, %offset;
    add.u64 %out_addr, %out_ptr, %offset;

    // load input half
    ld.global.f16 %f_in, [%in_addr];

    // sigmoid = 1 / (1 + exp(-x))
    cvt.f32.f16 %f32_tmp, %f_in;   // half -> float32
    neg.f32 %f32_tmp, %f32_tmp;   // -x
    .exp.approx.f32 %f32_tmp, %f32_tmp; // exp(-x) (approximate)
    add.f32 %f32_tmp, %f32_tmp, 1.0; // 1 + exp(-x)
    rcp.approx.f32 %f32_tmp, %f32_tmp; // 1 / (1 + exp(-x))

    // back to half (round‑to‑nearest)
    cvt.rn.f16.f32 %f_out, %f32_tmp;

    // store result
    st.global.f16 [%out_addr], %f_out;

    ret;
}
"""

